package br.com.sussmartcare.triage.adapters.in.rest; import br.com.sussmartcare.triage.application.*; import br.com.sussmartcare.triage.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/triages") public class TriageController {private final TriageApplicationService app;public TriageController(TriageApplicationService a){app=a;}public record StartRequest(@NotNull UUID visitId){}public record AssessmentRequest(@NotNull ClinicalPriority recommendation,@DecimalMin("0.0") @DecimalMax("1.0") double confidence,@NotBlank String reasoning){}public record DecisionRequest(@NotNull ClinicalPriority priority,@NotNull UUID professionalId){}
 @PostMapping public ResponseEntity<Triage> start(@Valid @RequestBody StartRequest r){return ResponseEntity.status(201).body(app.start(r.visitId()));}@GetMapping("/{id}") public Triage get(@PathVariable UUID id){return app.get(id);}@GetMapping("/by-visit/{visitId}") public ResponseEntity<Triage> byVisit(@PathVariable UUID visitId){try{return ResponseEntity.ok(app.getByVisit(visitId));}catch(IllegalArgumentException ex){return ResponseEntity.notFound().build();}}@PostMapping("/{id}/assessment") public Triage assess(@PathVariable UUID id,@Valid @RequestBody AssessmentRequest r){return app.assess(id,r.recommendation(),r.confidence(),r.reasoning());}@PostMapping("/{id}/assessment/ai") public Triage assessWithAi(@PathVariable UUID id){return app.assessWithAi(id);}@PostMapping("/{id}/decision") public Triage decision(@PathVariable UUID id,@Valid @RequestBody DecisionRequest r){return app.confirm(id,r.priority(),r.professionalId());}}
